import base64, fnmatch, http.client, json, re, socket, time, urllib.error as _ue, urllib.parse as _up, urllib.request as _ur
try:
    from owe_python_sdk.runtime import execution_context as _ctx
except Exception:
    _ctx = None

def _input(name, default="", allow_environment=True):
    value = None
    if _ctx is not None:
        try:
            value = _ctx.get_input(name)
        except Exception:
            value = None
    # Hosted composite tasks must receive the caller's token through
    # the workflow argument binding.  Environment fallback remains
    # useful for local/generated-code tests, but is never consulted
    # when the hosted execution context is present and the caller
    # token is requested with allow_environment=False.
    if value in (None, "") and (allow_environment or _ctx is None):
        import os
        value = os.environ.get(name, default)
    return default if value in (None, "") else value

_signal_url = _input("SIGNAL_URL", "", allow_environment=False).strip()
_signal_token = _input("SIGNAL_TOKEN", "", allow_environment=False).strip()
_signal_expires = _input("SIGNAL_EXPIRES", "", allow_environment=False).strip()

def _signal(event, retry_for=5, **fields):
    # Best-effort liveness report to the adapter (app/run_state.py). It
    # never changes this task's outcome, and never prints the request,
    # the token or an exception: Workflows captures stdout.
    if not (_signal_url and _signal_token):
        return
    payload = {"schema": 1, "event": event, "task_id": "model", "attempt": 1}
    payload.update({k: v for k, v in fields.items() if v is not None})
    request = _ur.Request(
        _signal_url, data=json.dumps(payload).encode(), method="POST",
        headers={"Content-Type": "application/json",
                 "X-Run-Signal-Token": _signal_token,
                 "X-Run-Signal-Expires": _signal_expires})
    deadline = time.time() + retry_for
    delay = 1
    while True:
        try:
            with _ur.urlopen(request, timeout=5):
                return
        except Exception:
            if time.time() >= deadline:
                return
            time.sleep(delay)
            delay = min(delay * 2, 10)

# First action: the staleness sweep treats silence after dispatch as a
# task that never ran, so this must go out before anything can fail.
_signal("started", retry_for=60)

_attempts = []

def _die(message, code="MODEL_OUTPUT_DISCOVERY_FAILED", details=None):
    payload = {"schema_version": 1, "status": "error", "code": code,
               "message": message, "attempts": _attempts[-40:]}
    if details:
        payload["details"] = details
    text = json.dumps(payload)
    if _ctx is not None:
        try:
            _ctx.set_output("result", text)
        except Exception:
            pass
    print(text)
    _signal("finished", code=code, message=message[:500],
            job_uuid=(details or {}).get("job_uuid"),
            job_status=(details or {}).get("status"))
    # SystemExit is rendered by Tapis Workflows as `Task Failed: []`,
    # discarding the structured diagnostic.  A bounded RuntimeError
    # keeps the task failed while preserving the safe category/message
    # in the workflow task's last_message.
    raise RuntimeError("%s: %s" % (code, message))

_base = _input("TAPIS_BASE_URL", "https://portals.tapis.io").rstrip("/")
_token = _input("TAPIS_TOKEN", "", allow_environment=False).strip()
_job_definition = {'name': 'mint-workflow-model-x', 'appId': 'modflow6-simulation', 'appVersion': '0.0.test', 'archiveSystemId': 'ls6', 'fileInputs': [], 'parameterSet': {'appArgs': []}, 'execSystemInputDir': '${JobWorkingDir}', 'execSystemOutputDir': '${JobWorkingDir}/output'}
_job_name = 'mint-workflow-model-x'
_output_name = 'cbb'.lower()
_output_format = 'cbc'.lower()
_output_file = ''
_renew_ttl = 0
if _output_file and (not re.fullmatch('^[A-Za-z0-9._\\-*?\\[\\]{}:]{1,255}$', _output_file)
                     or _output_file in (".", "..") or "{param:" in _output_file
                     or _output_file.lower().startswith("tapisjob")):
    _die("model output file binding is not a valid archive file name",
         "MODEL_OUTPUT_FILE_INVALID", {"output_file": _output_file[:255]})
if not _token:
    _die("TAPIS_TOKEN is required for the composite model stage", "MODEL_SUBMISSION_AUTH_REQUIRED")
# The live token sits in a dict so renewal can swap it without rebinding a global.
_auth = {"token": _token, "retry_at": 0.0}

def _claims(token):
    try:
        payload = token.split(".")[1]
        payload += "=" * (-len(payload) % 4)
        return json.loads(base64.urlsafe_b64decode(payload))
    except Exception:
        return {}

def _renew_if_due(force=False):
    # Mint a fresh token from the live one before it expires, so the wait is
    # bounded by the job and not by any single token's lifetime. A failed
    # renewal is retried shortly; the current token keeps working until it
    # actually expires, and a rejected token still ends the stage.
    # force=True skips the due check; it is used once, at the end, to hand
    # the next stage a token with a full lifetime.
    if not _renew_ttl or (not force and time.time() < _auth["retry_at"]):
        return
    claims = _claims(_auth["token"])
    expires_at = claims.get("exp")
    if not force and (not expires_at or int(expires_at) - time.time() > max(300, _renew_ttl // 4)):
        return
    body = {
        "token_tenant_id": claims.get("tapis/tenant_id") or "portals",
        "account_type": "user",
        "token_username": claims.get("tapis/username"),
        "target_site_id": "svo-adapter-run-%x" % int(time.time()),
        "access_token_ttl": _renew_ttl,
    }
    request = _ur.Request(
        _base + "/v3/tokens", data=json.dumps(body).encode(),
        headers={"X-Tapis-Token": _auth["token"], "Content-Type": "application/json"},
        method="POST")
    try:
        with _ur.urlopen(request, timeout=90) as response:
            fresh = (((json.loads(response.read().decode()) or {}).get("result") or {})
                     .get("access_token") or {}).get("access_token")
    except Exception:
        fresh = None
    if fresh:
        _auth["token"] = fresh
    else:
        _auth["retry_at"] = time.time() + 30

# Token keeper (adapter run_tokens.py): the engine can start this task
# hours after dispatch, after the token in the args has expired. The
# adapter keeps a live copy and serves it at TOKEN_URL to the holder of
# this run's fetch credential. Best effort and silent, like _signal:
# nothing here prints, and a failed fetch just leaves the current token.
_token_url = _input("TOKEN_URL", "", allow_environment=False).strip()
_fetch_cred = _input("TOKEN_FETCH_TOKEN", "", allow_environment=False).strip()
_fetch_expires = _input("TOKEN_FETCH_EXPIRES", "", allow_environment=False).strip()
_auth["fetches"] = 0

def _fetch_token():
    # True when a different, non-empty token was installed.
    if not (_token_url and _fetch_cred) or _auth["fetches"] >= 20:
        return False
    _auth["fetches"] += 1
    request = _ur.Request(
        _token_url, data=b"", method="POST",
        headers={"X-Run-Token-Credential": _fetch_cred,
                 "X-Run-Token-Expires": _fetch_expires,
                 "Accept": "application/json"})
    for _try in range(3):
        try:
            with _ur.urlopen(request, timeout=5) as response:
                fresh = ((json.loads(response.read().decode()) or {}).get("token") or "").strip()
            _note({"method": "FETCH", "path": "run-token", "status": "ok" if fresh else "empty"})
            if fresh and fresh != _auth["token"]:
                _auth["token"] = fresh
                return True
            return False
        except _ue.HTTPError as exc:
            _note({"method": "FETCH", "path": "run-token", "status": exc.code})
            if exc.code in (401, 404, 429):
                return False  # refused for good; do not hammer the adapter
        except Exception:
            _note({"method": "FETCH", "path": "run-token", "status": "transport_error"})
        time.sleep(2 * (_try + 1))
    return False

def _token_expired_or_due():
    expires_at = _claims(_auth["token"]).get("exp")
    if not expires_at:
        return False
    margin = max(300, (_renew_ttl or 0) // 4)
    return int(expires_at) - time.time() <= margin

class _Transient(Exception):
    pass

def _note(entry):
    _attempts.append(entry)
    del _attempts[:-200]

def _request(path, method="GET", payload=None, tolerate=False, auth_retry=True):
    # tolerate=True raises _Transient for network errors and 5xx/429 so a
    # long wait can ride out an outage. A 401 (expired token) gets one
    # fetch from the adapter's token keeper and one retry; 403 is a real
    # authorization failure and ends the stage at once.
    body = None if payload is None else json.dumps(payload).encode()
    headers = {"X-Tapis-Token": _auth["token"], "Accept": "application/json"}
    if body is not None:
        headers["Content-Type"] = "application/json"
    request = _ur.Request(_base + path, data=body, headers=headers, method=method)
    try:
        with _ur.urlopen(request, timeout=90) as response:
            _note({"method": method, "path": path, "status": response.getcode()})
            return json.loads(response.read().decode())
    except _ue.HTTPError as exc:
        _note({"method": method, "path": path, "status": exc.code})
        if exc.code == 401 and auth_retry and _fetch_token():
            if method == "POST" and path.endswith("/jobs/submit"):
                # Tapis may have accepted the job before the 401 surfaced;
                # attach to it by name rather than submit a duplicate.
                _dup = _existing_job()
                if _dup:
                    _note({"method": "ATTACH", "path": "/v3/jobs/" + _dup, "status": "existing_job"})
                    return {"result": {"uuid": _dup}}
            return _request(path, method, payload, tolerate, auth_retry=False)
        if exc.code in (401, 403):
            _die(
                "the UI Tapis token was rejected during model %s (HTTP %s)"
                % (method.lower(), exc.code),
                "MODEL_PROVIDER_AUTH_FAILED",
                {"http_status": exc.code, "operation": method.lower(), "path": path},
            )
        if tolerate and (exc.code >= 500 or exc.code in (408, 429)):
            raise _Transient()
        _die("Tapis model request failed with HTTP %s" % exc.code,
             "MODEL_PROVIDER_REQUEST_FAILED")
    except (_ue.URLError, OSError, http.client.HTTPException, ValueError) as exc:
        _note({"method": method, "path": path,
               "status": "transport_error", "error": type(exc).__name__})
        if tolerate:
            raise _Transient()
        _die("Tapis model request failed: %s" % type(exc).__name__,
             "MODEL_PROVIDER_REQUEST_FAILED")

def _request_retry(path):
    # One-off reads after the job finished: a blip here must not discard the run.
    for _try in range(6):
        try:
            return _request(path, tolerate=True)
        except _Transient:
            time.sleep(10)
    _die("Tapis kept failing after the model job finished",
         "MODEL_PROVIDER_REQUEST_FAILED")

def _find(value, names):
    if isinstance(value, dict):
        for name in names:
            if value.get(name):
                return value[name]
        for child in value.values():
            found = _find(child, names)
            if found:
                return found
    elif isinstance(value, list):
        for child in value:
            found = _find(child, names)
            if found:
                return found
    return None

def _existing_job():
    # The Workflows engine can fail this task (e.g. a Kubernetes 504 while it
    # polls) after the Tapis job was already submitted, and may then retry the
    # task. Attach to that job instead of submitting a duplicate. Job names are
    # unique per execution, and a failed/cancelled job is not worth attaching to.
    if not _job_name:
        return None
    _found = _request_retry(
        "/v3/jobs/list?search=name.eq.%s&select=uuid,name,status,created"
        "&orderBy=created(desc)" % _up.quote(_job_name, safe=""))
    for _candidate in ((_found or {}).get("result") or []):
        if not isinstance(_candidate, dict) or _candidate.get("name") != _job_name:
            continue
        _state = str(_candidate.get("status") or "").upper()
        if _state in {"FAILED", "CANCELLED", "CANCELED", "KILLED", "SYSTEM_ERROR"}:
            continue
        if _candidate.get("uuid"):
            return str(_candidate["uuid"])
    return None

# Late start (the engine held this task past the baked token's life):
# swap in a live token before the first Tapis call, and say so clearly
# if none can be had, instead of a misleading "token rejected".
if _token_expired_or_due():
    _fetched = _fetch_token()
    _exp = _claims(_auth["token"]).get("exp")
    if not _fetched and _exp and int(_exp) <= time.time():
        _die("the run token expired before the model task started and no live "
             "token could be fetched from the adapter",
             "RUN_TOKEN_EXPIRED_BEFORE_START",
             {"token_fetch_configured": bool(_token_url and _fetch_cred)})

_credentials_url = _input("CREDENTIALS_URL", "", allow_environment=False).strip()

def _submit_definition():
    # Copy of _job_definition for the submit call only: the secrets bound
    # to this run are fetched from the adapter (authorised by the signal
    # token) and added to the copy in memory. _job_definition itself,
    # and anything printed about it, never holds the values.
    _definition = json.loads(json.dumps(_job_definition))
    _inputs = _definition.get("fileInputs")
    if isinstance(_inputs, list):
        # A user-supplied netrc must never override the system credential.
        _definition["fileInputs"] = [
            _i for _i in _inputs
            if not (isinstance(_i, dict) and _i.get("name") == "earthdata-netrc")]
    if not _credentials_url:
        return _definition
    if not _signal_token:
        _die("credential endpoint configured but no run signal token was issued",
             code="SECRET_UNAVAILABLE")
    _creds = None
    for _try in range(3):
        try:
            with _ur.urlopen(_ur.Request(
                    _credentials_url, method="GET",
                    headers={"X-Run-Signal-Token": _signal_token,
                             "X-Run-Signal-Expires": _signal_expires,
                             "Accept": "application/json"}), timeout=10) as _resp:
                _creds = json.loads(_resp.read().decode()) or {}
            break
        except _ue.HTTPError as exc:
            _note({"method": "FETCH", "path": "run-credentials", "status": exc.code})
            if exc.code < 500 and exc.code != 429:
                break  # 404/403/409: the run bound secrets, so this is a failure
        except Exception:
            _note({"method": "FETCH", "path": "run-credentials", "status": "transport_error"})
        time.sleep(2 * (_try + 1))
    _env_values = _creds.get("env") if isinstance(_creds, dict) else None
    if not (isinstance(_env_values, dict) and _env_values):
        _die("could not obtain the run's secrets from the adapter",
             "SECRET_UNAVAILABLE")
    _params = _definition.setdefault("parameterSet", {})
    _env = _params.get("envVariables")
    if not isinstance(_env, list):
        _env = _params["envVariables"] = []
    for _key, _value in _env_values.items():
        # Replace, never duplicate: Tapis rejects repeated env keys.
        _env[:] = [_e for _e in _env if not (isinstance(_e, dict) and _e.get("key") == _key)]
        _env.append({"key": str(_key), "value": str(_value)})
    return _definition

_job_uuid = _existing_job()
if _job_uuid:
    _note({"method": "ATTACH", "path": "/v3/jobs/" + _job_uuid, "status": "existing_job"})
else:
    _submitted = _request("/v3/jobs/submit", method="POST", payload=_submit_definition())
    _job_uuid = _find(_submitted, {"uuid", "jobUuid", "jobUUID"})
    if not _job_uuid:
        _die("Tapis did not return a model job UUID", "MODEL_PROVIDER_JOB_ID_MISSING")
    _job_uuid = str(_job_uuid)
_signal("job_submitted", job_uuid=_job_uuid, job_name=_job_name,
        attached=bool(_attempts and _attempts[-1].get("status") == "existing_job"))
_status_path = "/v3/jobs/%s/status" % _up.quote(_job_uuid, safe="")
_terminal = None
_last_ok = time.time()
while True:
    _renew_if_due()
    try:
        _status_payload = _request(_status_path, tolerate=True)
    except _Transient:
        # Ride out a Tapis/network outage; give up only if it persists.
        if time.time() - _last_ok > 1800:
            _die("Tapis job status was unreachable for over %d seconds" % 1800,
                 "MODEL_PROVIDER_REQUEST_FAILED", {"job_uuid": _job_uuid})
        time.sleep(15)
        continue
    _last_ok = time.time()
    _status_result = ((_status_payload or {}).get("result")
                      if isinstance(_status_payload, dict) else None)
    _status = str(_find(_status_result, {"status", "state", "job_status", "jobStatus"})
                  or _find(_status_payload, {"state", "job_status", "jobStatus"})
                  or "").upper().replace(" ", "_")
    if _status in {
        "FINISHED",
        "COMPLETED",
        "SUCCESS",
        "SUCCEEDED",
        "NORMAL_COMPLETION",
    }:
        _terminal = _status
        break
    if _status in {"FAILED", "CANCELLED", "CANCELED", "KILLED", "SYSTEM_ERROR"}:
        _die("model job %s ended with status %s" % (_job_uuid, _status),
             "MODEL_PROVIDER_JOB_FAILED", {"job_uuid": _job_uuid, "status": _status})
    time.sleep(5)

_detail = _request_retry("/v3/jobs/%s" % _up.quote(_job_uuid, safe=""))
_job = (_detail.get("result") if isinstance(_detail, dict) else None) or {}
# Tapis pages the listing (default 100 entries), so walk it explicitly.
_page_size, _max_pages = 1000, 5
_listed = []
_truncated = False
for _page in range(_max_pages):
    _files_payload = _request_retry("/v3/jobs/%s/output/list/?limit=%d&skip=%d" % (
        _up.quote(_job_uuid, safe=""), _page_size, _page * _page_size))
    _files_result = (_files_payload or {}).get("result") or []
    if isinstance(_files_result, dict):
        _files_result = (_files_result.get("files") or _files_result.get("items") or
                         _files_result.get("results") or [])
    _listed.extend(_files_result)
    if len(_files_result) < _page_size:
        break
else:
    _truncated = True
_files = [entry for entry in _listed if isinstance(entry, dict) and entry.get("type") != "dir"
          and not str(entry.get("name") or "").lower().startswith("tapisjob")]
_names = [str(entry.get("name") or "") for entry in _files]

def _output_details(**extra):
    details = {"job_uuid": _job_uuid, "output_file": _output_file or None,
               "output_name": _output_name, "archived_files": _names[:40],
               "listed": len(_files), "truncated": _truncated}
    details.update(extra)
    return details

_selected_by = "name"
if _output_file:
    _selected_by = "binding"
    _is_glob = "*" in _output_file or "?" in _output_file
    _matches = [entry for entry in _files if (
        fnmatch.fnmatchcase(str(entry.get("name") or ""), _output_file) if _is_glob
        else str(entry.get("name") or "") == _output_file)]
    if not _matches:
        _ext = _output_file.rsplit(".", 1)[1] if "." in _output_file else ""
        _candidates = [n for n in _names if _ext and n.endswith("." + _ext)]
        _die("model output file %s was not found in the job archive" % _output_file,
             "MODEL_OUTPUT_MISSING",
             _output_details(candidates=_candidates[:20],
                             hint="re-register the configuration's output binding"))
    if len(_matches) > 1:
        _die("model output file %s matched %d archived files" % (_output_file, len(_matches)),
             "MODEL_OUTPUT_AMBIGUOUS", _output_details())
    _selected = _matches[0]
else:
    _wanted = _output_name
    _exact = [entry for entry in _files if str(entry.get("name") or "").lower() == _wanted]
    if len(_exact) == 1:
        _selected = _exact[0]
    else:
        _extensions = ([".cbc", ".cbb"] if _wanted in {"cbc", "cbb"} or "cbc" in _output_format
                       else (["." + _wanted] if _wanted else []))
        _matches = [entry for entry in _files if any(
            str(entry.get("name") or "").lower().endswith(ext) for ext in _extensions)]
        if len(_matches) != 1:
            _die("model output %s was not uniquely matched" % _output_name,
                 "MODEL_OUTPUT_AMBIGUOUS", _output_details())
        _selected = _matches[0]

_url = str(_selected.get("url") or _selected.get("uri") or "")
_parsed = _up.urlparse(_url)
if _parsed.scheme == "tapis" and _parsed.netloc and _parsed.path:
    _resource_uri = _url
else:
    _system = str(_job.get("archiveSystemId") or _job.get("archive_system_id") or
                  _job_definition.get("archiveSystemId") or "")
    _path = str(_selected.get("path") or "").lstrip("/")
    if not _system or not _path:
        _die("Tapis did not return a complete path for the selected model output",
             "MODEL_OUTPUT_PATH_MISSING", {"job_uuid": _job_uuid})
    _resource_uri = "tapis://%s/%s" % (_system, _path)
_manifest = {"schema_version": 1, "status": "ok", "resource_uri": _resource_uri,
             "model_output_key": _output_name, "model_job_name": _job_name,
             "model_job_uuid": _job_uuid, "archived_name": _selected.get("name"),
             "output_file": _output_file or None, "selected_by": _selected_by}
# Later stages run after this wait, possibly past the lifetime of the token
# the run was submitted with, so hand them this stage's live token. A failed
# mint keeps the current token, which Tapis may still accept.
_renew_if_due(force=True)
if _ctx is not None:
    try:
        _ctx.set_output("result", _resource_uri)
        _ctx.set_output("token", _auth["token"])
    except Exception:
        pass
_signal("finished", job_uuid=_job_uuid, job_status=_terminal,
        condition=str(_job.get("condition") or "") or None)
print(json.dumps(_manifest))

import json, os
try:
    from owe_python_sdk.runtime import execution_context as _ctx
except Exception:
    _ctx = None

def _input(name, default=""):
    value = None
    if _ctx is not None:
        try:
            value = _ctx.get_input(name)
        except Exception:
            value = None
    if value in (None, ""):
        value = os.environ.get(name, default)
    return default if value in (None, "") else value

def _input_alias(canonical, *legacy, default=""):
    # Read canonical task input first, then historical environment names.
    for name in (canonical, *legacy):
        value = _input(name, "")
        if value not in (None, ""):
            return value
    return default

def _emit_result(result):
    # Keep stdout as a bounded, inspectable record while also publishing the
    # same value through the Workflows function-task output contract. The
    # latter is the typed handoff consumed by downstream tasks.
    text = json.dumps(result)
    if _ctx is not None:
        try:
            _ctx.set_output("result", text)
        except Exception:
            pass
    print(text)

def _die(message):
    # Keep task failures structured so Workflows and the facilitator UI can
    # distinguish a failed transform from a successful JSON result.
    text = json.dumps({"schema_version": 1, "status": "error", "message": message})
    if _ctx is not None:
        try:
            _ctx.set_output("result", text)
        except Exception:
            pass
    print(text)
    raise SystemExit(1)
import json, socket, time, urllib.error as _ue, urllib.request as _ur

def _actor_run(msg):
    _base = _input("TAPIS_BASE_URL", "https://portals.tapis.io").rstrip("/")
    _aid  = _input("GEO_ACTOR_ID", "").strip()
    _tok  = _input("TAPIS_TOKEN", "").strip()
    if not _aid:
        _die("GEO_ACTOR_ID is required for geo_actor-backed DFC transforms")
    if not _tok:
        _die("TAPIS_TOKEN is required so the geo_actor can read Tapis/CKAN inputs")
    _hdr  = {"X-Tapis-Token": _tok, "Content-Type": "application/json"}
    def _req(method, url, body=None, attempts=1):
        d = json.dumps(body).encode() if body else None
        raw = ""
        for _attempt in range(1, attempts + 1):
            r = _ur.Request(url, data=d, headers=_hdr, method=method)
            try:
                raw = _ur.urlopen(r, timeout=90).read().decode()
                break
            except _ue.HTTPError as exc:
                err = exc.read().decode(errors="replace")[:800]
                _die(f"Tapis geo_actor API {method} failed with HTTP {exc.code}: {err}")
            except (_ue.URLError, TimeoutError, socket.timeout) as exc:
                if _attempt >= attempts:
                    _die(f"Tapis geo_actor API {method} failed after {attempts} attempts: {type(exc).__name__}: {exc}")
                time.sleep(min(2 ** _attempt, 20))
            except Exception as exc:
